pub fn family(tool: &str) -> Family {
    match tool {
        "Bash" => Family::Bash,
        "Edit" | "Write" | "MultiEdit" | "NotebookEdit" | "ApplyPatch" => Family::Edit,
        "Read" | "Grep" | "Glob" => Family::Read,
        "WebFetch" => Family::WebFetch,
        _ => Family::Other,
    }
}

fn load_defs() -> Result<BTreeMap<AgentName, AgentDef>, AgentsError> {
    let mut out = BTreeMap::new();
    for agent in AgentName::ALL {
        let path = format!("agents/{}/agent.toml", agent.as_str());
        let raw: AgentToml =
            toml::from_str(&asset_text(&path)?).map_err(|e| AgentsError::Parse {
                path: path.clone(),
                message: e.to_string(),
            })?;
        out.insert(
            agent,
            AgentDef {
                name: agent,
                description: raw.description,
                default_tier: raw.default_tier,
                effort: raw.effort,
                capabilities: raw.capabilities,
                timeout_secs: raw.timeout_seconds,
            },
        );
    }
    Ok(out)
}

pub(crate) fn tool(
    &self,
    capability: &str,
    executor: ExecutorKind,
    agent: AgentName,
) -> Option<String> {
    let (key, op) = capability
        .split_once(':')
        .map_or((capability, None), |(k, o)| (k, Some(o)));
    let value = self.capabilities.get(key)?.get(executor.tier_table())?;
    let mut v = value.replace("{agent}", &agent.snake());
    if let Some(op) = op {
        let mut cap = op.to_string();
        cap[..1].make_ascii_uppercase();
        v = v.replace("{op}", op).replace("{Op}", &cap);
    }
    Some(v)
}

